// Client-side search over /assets/search-index.json (generated by build.py).
(async function () {
  const input = document.getElementById('q');
  const results = document.getElementById('results');
  const filterBar = document.getElementById('filters');
  const params = new URLSearchParams(location.search);
  let kind = params.get('kind') || 'all';
  input.value = params.get('q') || '';

  let items = [];
  try {
    items = await (await fetch('/assets/search-index.json')).json();
  } catch (e) {
    results.innerHTML = '<p class="empty">Could not load the search index.</p>';
    return;
  }

  const esc = s => s.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const norm = s => s.toLowerCase().replace(/[^a-z0-9 ]+/g, ' ');

  function render() {
    // Every word must appear somewhere; "notes"/"mcq" in the query also act as kind filters.
    const words = norm(input.value).split(/\s+/).filter(Boolean);
    const hits = items.filter(x => (kind === 'all' || x.kind === kind) &&
      words.every(w => x.haystack.includes(w)));
    results.innerHTML = hits.map(x => `
      <article class="card kind-${x.kind}">
        <div><span class="badge ${x.kind}">${x.kind === 'mcq' ? 'MCQ' : 'Notes'}</span></div>
        <h3><a href="${x.url}">${esc(x.title)}</a></h3>
        <div class="meta">Grade ${x.grade} · ${esc(x.chapter)}</div>
      </article>`).join('') ||
      '<p class="empty">No matching lessons yet. Try a chapter name such as “waves” or “heat”.</p>';
    filterBar.querySelectorAll('button').forEach(b => b.setAttribute('aria-pressed', b.dataset.kind === kind));
    const qs = new URLSearchParams();
    if (input.value.trim()) qs.set('q', input.value.trim());
    if (kind !== 'all') qs.set('kind', kind);
    history.replaceState(null, '', qs.toString() ? '?' + qs : location.pathname);
  }

  input.addEventListener('input', render);
  document.getElementById('search-form').addEventListener('submit', e => { e.preventDefault(); render(); });
  filterBar.addEventListener('click', e => {
    if (e.target.dataset.kind) { kind = e.target.dataset.kind; render(); }
  });
  render();
})();
